<?php
declare(strict_types=1);namespace Vendi\Sales;use PDO;use RuntimeException;
final class RefundService{public function __construct(private PDO $db,private ?ReturnTraceabilityService $trace=null){}
 public function refund(int$b,int$branch,int$u,int$saleId,array$requested,string$reason,array$payments=[]):int{if(trim($reason)===''||!$requested)throw new RuntimeException('Selecciona artículos y captura el motivo.');$this->db->beginTransaction();try{$s=$this->db->prepare("SELECT id,status FROM sales WHERE id=? AND business_id=? AND branch_id=? FOR UPDATE");$s->execute([$saleId,$b,$branch]);$sale=$s->fetch();if(!$sale||$sale['status']!=='completed')throw new RuntimeException('La venta no admite devolución.');$total=0;$lines=[];foreach($requested as$r){$q=$this->db->prepare("SELECT si.*,COALESCE((SELECT SUM(ri.qty) FROM refund_items ri JOIN refunds rf ON rf.id=ri.refund_id WHERE ri.sale_item_id=si.id AND rf.status='completed'),0) returned FROM sale_items si WHERE si.id=? AND si.sale_id=? FOR UPDATE");$q->execute([(int)$r['sale_item_id'],$saleId]);$i=$q->fetch();if(!$i)throw new RuntimeException('Partida inválida.');$qty=(float)$r['qty'];$available=(float)$i['qty']-(float)$i['returned'];if($qty<=0||$qty>$available)throw new RuntimeException('Cantidad de devolución inválida.');$amount=round((float)$i['line_total']/(float)$i['qty']*$qty,2);$total+=$amount;$lines[]=[$i,$qty,$amount];}$this->db->prepare("INSERT INTO refunds(business_id,branch_id,sale_id,user_id,reason,total) VALUES(?,?,?,?,?,?)")->execute([$b,$branch,$saleId,$u,trim($reason),round($total,2)]);$rid=(int)$this->db->lastInsertId();foreach($lines as[$i,$qty,$amount]){$this->db->prepare("INSERT INTO refund_items(refund_id,sale_item_id,product_id,qty,amount) VALUES(?,?,?,?,?)")->execute([$rid,$i['id'],$i['product_id'],$qty,$amount]);$ri=(int)$this->db->lastInsertId();($this->trace??new ReturnTraceabilityService($this->db))->restore($b,$branch,$u,$rid,$ri,$i,$qty);}$paid=0;foreach($payments as$p){$a=(float)($p['amount']??0);if($a<=0)continue;$paid+=$a;$this->db->prepare("INSERT INTO refund_payments(refund_id,payment_method_id,method,amount,reference) VALUES(?,?,?,?,?)")->execute([$rid,$p['payment_method_id']??null,$p['method'],$a,$p['reference']??null]);}if($payments&&round($paid,2)!==round($total,2))throw new RuntimeException('El reembolso debe coincidir con el total devuelto.');$left=$this->db->prepare("SELECT SUM(si.qty-COALESCE((SELECT SUM(ri.qty) FROM refund_items ri JOIN refunds rf ON rf.id=ri.refund_id WHERE ri.sale_item_id=si.id AND rf.status='completed'),0)) FROM sale_items si WHERE si.sale_id=?");$left->execute([$saleId]);if((float)$left->fetchColumn()<=0)$this->db->prepare("UPDATE sales SET status='refunded' WHERE id=?")->execute([$saleId]);$this->db->commit();return$rid;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
}